css:
.wrap { max-width: 1360px; margin: 0 auto; }

footer { padding: 48px 40px; position: relative; z-index: 2; }
.footer-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; margin-bottom: 40px; }
.footer-brand { font-family: 'Sora', sans-serif; font-weight: 800; font-size: 20px; margin-bottom: 14px; }
.footer-brand span { color: var(--accent); font-weight: 400; }
.footer-desc { font-family: 'Manrope', sans-serif; font-size: 13px; color: #666; line-height: 1.6; max-width: 280px; }
.footer-col-title { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: #666; letter-spacing: 0.15em; text-transform: uppercase; margin-bottom: 14px; }
.footer-links { display: flex; flex-direction: column; gap: 8px; font-family: 'Manrope', sans-serif; font-size: 14px; }
.footer-links a { color: #d4d4d4; }
.footer-bottom {
  padding-top: 24px; border-top: 1px solid var(--border); display: flex; justify-content: space-between;
  align-items: center; font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-dimmer);
  letter-spacing: 0.08em; flex-wrap: wrap; gap: 12px;
}
.footer-bottom span:last-child span { color: #fff; }

@media (max-width: 700px) {
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
